BEGIN;

-- Run once (seed_runs). Brings the West Bengal VS 2011-2021 rows of an existing DB to the real ECI values before the
-- West Bengal VS seeds run: deletes the old rows ECI does not have (decided in scraper/data/wb/decisions.json),
-- fixes votes/status/margin, candidate names/party/age, constituency type/electors/turnout/phase, and renames
-- auto-created single-candidacy persons still carrying the old name. The VS seeds then insert the missing
-- candidates. On a fresh DB there are no West Bengal rows yet: the body is skipped and only the marker is written.
-- Generated by scraper/src/bihar/generate-cli.ts. Do not edit by hand.
SELECT NOT EXISTS (SELECT 1 FROM seed_runs WHERE name = 'seed_wb_corrections_v1')
   AND EXISTS (SELECT 1 FROM constituencies WHERE election_id = 'd4e5f6a7-b8c9-0123-def0-345678901011')
   AS seed_apply \gset
\if :seed_apply

-- Pre-flight: this DB must hold exactly the old seeds' West Bengal candidates, with their seeded parties.
CREATE TEMP TABLE wb_old_seed (id uuid PRIMARY KEY, party_id text) ON COMMIT DROP;
