DO $$
DECLARE unknown int; moved int;
BEGIN
  SELECT count(*) INTO unknown FROM candidates c WHERE c.election_id IN ('d4e5f6a7-b8c9-0123-def0-345678901011', 'd4e5f6a7-b8c9-0123-def0-345678901016', 'd4e5f6a7-b8c9-0123-def0-345678901021')
    AND NOT EXISTS (SELECT 1 FROM wb_old_seed o WHERE o.id = c.id);
  SELECT count(*) INTO moved FROM candidates c JOIN wb_old_seed o ON o.id = c.id WHERE c.party_id IS DISTINCT FROM o.party_id;
  IF unknown > 0 OR moved > 0 THEN
    RAISE EXCEPTION 'seed_wb_corrections_v1: % West Bengal candidates are not in the old seeds and % changed party since; reconcile them first (docs/DEPLOYMENT.md 5.0a)', unknown, moved;
  END IF;
END $$;

